import { Controller, Get, Logger, Post, Req } from '@nestjs/common';
import { AppService } from './app.service';
import { Request } from 'express';
import { AppConfigService } from './config/app-config/app-config.service';

const INPUT_BINDING_ROUTE = process.env.INPUT_BINDING_NAME || 'main-topic-in';

@Controller()
export class AppController {
  public constructor(
    private readonly appService: AppService,
    private readonly appConfigService: AppConfigService,
  ) {}

  @Get()
  public getHello(): string {
    return `Changed => ${this.appService.getHello()}`;
  }

  @Get('invk')
  public async invokeApi(): Promise<string | object> {
    return await this.appService.invokeApi();
  }

  @Get('db')
  public async readFromDatabse(): Promise<string[]> {
    return await this.appService.getFromDb();
  }

  @Get('secrets')
  public async readSecrets(): Promise<string> {
    return await this.appService.getSecrets();
  }

  @Get('secrets-dapr')
  public async readSecretsDapr(): Promise<string> {
    return await this.appService.getSecretViaDapr();
  }

  @Post('send')
  public async sendEvent(): Promise<string> {
    const eventId = await this.appService.sendEvent();
    return `Event Sent ${eventId}`;
  }

  @Post(INPUT_BINDING_ROUTE)
  public async receiveEvent(@Req() request: Request): Promise<string> {
    Logger.log(`Received event: ${JSON.stringify(request.body)}`);
    return 'Event Received';
  }
}

