import { Injectable, Logger } from '@nestjs/common';
import { AppConfigService } from './config/app-config/app-config.service';
import { DaprClient, HttpMethod } from '@dapr/dapr';
import { DatabaseService } from './database/database.service';
import * as fs from 'fs/promises';
import * as path from 'path';

@Injectable()
export class AppService {
  public constructor(
    private readonly appConfigService: AppConfigService,
    private readonly daprClient: DaprClient,
    private readonly databaseService: DatabaseService,
  ) {}

  public getHello(): string {
    return this.appConfigService.message;
  }

  public async getFromDb(): Promise<string[]> {
    return await this.databaseService.getAllPersonsNames();
  }

  public async getSecrets(): Promise<string> {
    const secretsPath = '/mnt/secrets-store';
    let result = '';

    try {
      // Read the directory contents
      const files = await fs.readdir(secretsPath);

      // Process each file
      for (const file of files) {
        const filePath = path.join(secretsPath, file);

        // Get file stats to check if it's a file
        const stats = await fs.stat(filePath);

        if (stats.isFile()) {
          // Read the file content
          const content = await fs.readFile(filePath, 'utf8');
          result += `File: ${filePath}\nContent: ${content}\n\n`;
        }
      }

      return result || 'No secret files found';
    } catch (error) {
      Logger.error(`Error reading secrets: ${error.message}`);
      return `Error reading secrets: ${error.message}`;
    }
  }
  public async getSecretViaDapr(): Promise<string> {
    try {
      const secretStoreName = 'secret-store';
      const secretKey = 'mes-mii-api-password';
      const secret = await this.daprClient.secret.get(
        secretStoreName,
        secretKey,
      );

      if (secret && Object.keys(secret).length > 0) {
        return `Secret successfully retrieved: ${JSON.stringify(secret)}`;
      } else {
        return 'Secret was empty or not found';
      }
    } catch (error) {
      Logger.error(`Error retrieving secret via Dapr: ${error.message}`);
      return `Error retrieving secret via Dapr: ${error.message}`;
    }
  }

  public async invokeApi(): Promise<string | object> {
    const targetAppId = this.appConfigService.providerAppId;
    if (targetAppId !== '') {
      Logger.log(`Calling app id: '${targetAppId}'`);
      const response = await this.daprClient.invoker.invoke(
        targetAppId,
        '/',
        HttpMethod.GET,
      );

      return response;
    } else {
      return 'No target app id found';
    }
  }

  public async sendEvent(): Promise<string> {
    const guid = crypto.randomUUID();
    await this.daprClient.binding.send(
      this.appConfigService.outputBindingName,
      'create',
      { message: guid },
      null,
    );
    return guid;
  }
}

