// Custom JSON logger implementation
class JsonLogger implements LoggerService {
  private logLevels: LogLevel[] = ['error', 'warn', 'log', 'debug', 'verbose'];

  constructor(
    private readonly context?: string,
    private readonly logLevels_?: LogLevel[],
  ) {
    if (logLevels_) {
      this.logLevels = logLevels_;
    }
  }

  error(message: any, trace?: string, context?: string): void {
    this.printLog('error', message, context || this.context, trace);
  }

  warn(message: any, context?: string): void {
    this.printLog('warn', message, context || this.context);
  }

  log(message: any, context?: string): void {
    this.printLog('log', message, context || this.context);
  }

  debug(message: any, context?: string): void {
    this.printLog('debug', message, context || this.context);
  }

  verbose(message: any, context?: string): void {
    this.printLog('verbose', message, context || this.context);
  }

  setContext(context: string) {
    return new JsonLogger(context, this.logLevels);
  }

  setLogLevels(levels: LogLevel[]) {
    this.logLevels = levels;
    return this;
  }

  private printLog(
    level: LogLevel,
    message: any,
    context?: string,
    trace?: string,
  ): void {
    if (!this.isLevelEnabled(level)) {
      return;
    }

    let formattedMessage: string;
    if (typeof message === 'object' && message !== null) {
      formattedMessage = JSON.stringify(message);
    } else {
      formattedMessage = message;
    }

    const logEntry = {
      timestamp: new Date().toISOString(),
      level,
      message: formattedMessage,
      context: context || 'NestApplication',
      ...(trace && { trace }),
    };

    const logString = JSON.stringify(logEntry);

    // Output to console based on log level
    if (level === 'error') {
      console.error(logString);
    } else if (level === 'warn') {
      console.warn(logString);
    } else {
      console.log(logString);
    }
  }

  private isLevelEnabled(level: LogLevel): boolean {
    return this.logLevels.includes(level);
  }
}

async function bootstrap() {
  // Create app with custom JSON logger
  const app = await NestFactory.create(AppModule, {
    logger: new JsonLogger(),
  });

  const appConfigService = (await NestFactory.create(AppConfigModule)).get(
    AppConfigService,
  );

  await app.listen(appConfigService.appPort);
}
bootstrap();

